// @FIGURE_CODE_BEGIN
var W = 680, H = 460;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var accent = '#e67e22';
var candidateColor = '#3b6eea';
var hullGray = '#a9a9a9';
var hullDark = '#222';

var points = {
  p0: { x: 210, y: 385, label: 'p₀' },
  p1: { x: 505, y: 350, label: 'p₁' },
  p2: { x: 560, y: 255, label: 'p₂' },
  p3: { x: 365, y: 70, label: 'p₃' },
  p4: { x: 110, y: 270, label: 'p₄' }
};

var hullOrder = ['p0', 'p1', 'p2', 'p3', 'p4'];
var nextOf = { p0: 'p1', p1: 'p2', p2: 'p3', p3: 'p4', p4: 'p0' };
var refAngle = { p0: 0, p1: 0, p2: 0, p3: Math.PI, p4: Math.PI };

var interiors = [
  { x: 190, y: 215 }, { x: 270, y: 205 }, { x: 340, y: 205 }, { x: 390, y: 190 },
  { x: 305, y: 240 }, { x: 500, y: 210 }, { x: 525, y: 255 }, { x: 485, y: 310 }
];

var base = draw.group();
var arcsLayer = draw.group();
var edgesLayer = draw.group();
var pointsLayer = draw.group();
var labelsLayer = draw.group();
var dynamic = draw.group();
var candidateLayer = draw.group();

function arrowLine(g, x1, y1, x2, y2, color, width, headLen, headWidth) {
  headLen = headLen || 14;
  headWidth = headWidth || 8;
  var line = g.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / len, uy = dy / len;
  var bx = x2 - ux * headLen, by = y2 - uy * headLen;
  var px = -uy, py = ux;
  g.polygon([
    [x2, y2],
    [bx + px * headWidth / 2, by + py * headWidth / 2],
    [bx - px * headWidth / 2, by - py * headWidth / 2]
  ]).fill(color).stroke('none');
  return line;
}

function mathAngle(from, to) {
  var a = Math.atan2(-(to.y - from.y), to.x - from.x);
  if (a < 0) a += Math.PI * 2;
  return a;
}

function sweepAngle(fromId, toPoint) {
  var a = mathAngle(points[fromId], toPoint);
  return (a - refAngle[fromId] + Math.PI * 2) % (Math.PI * 2);
}

function deg(rad) {
  return Math.round(rad * 180 / Math.PI);
}

function arcPath(cx, cy, start, end, r, steps) {
  steps = steps || 36;
  var d = '';
  for (var i = 0; i <= steps; i++) {
    var t = start + (end - start) * i / steps;
    var x = cx + r * Math.cos(t);
    var y = cy - r * Math.sin(t);
    d += (i === 0 ? 'M' : 'L') + x.toFixed(2) + ',' + y.toFixed(2);
  }
  return d;
}

function sectorPath(cx, cy, start, end, r, steps) {
  steps = steps || 36;
  var d = 'M' + cx + ',' + cy + ' ';
  for (var i = 0; i <= steps; i++) {
    var t = start + (end - start) * i / steps;
    var x = cx + r * Math.cos(t);
    var y = cy - r * Math.sin(t);
    d += (i === 0 ? 'L' : 'L') + x.toFixed(2) + ',' + y.toFixed(2) + ' ';
  }
  return d + 'Z';
}

function chosenEndAngle(id) {
  var raw = mathAngle(points[id], points[nextOf[id]]);
  while (raw < refAngle[id]) raw += Math.PI * 2;
  return raw;
}

function textHalo(g, txt, x, y, opts) {
  opts = opts || {};
  return g.text(txt)
    .move(x, y)
    .font({
      family: opts.family || 'Georgia, Times New Roman, serif',
      size: opts.size || 22,
      style: opts.style || 'italic',
      anchor: opts.anchor || 'start'
    })
    .fill(opts.fill || '#000')
    .attr({
      'paint-order': 'stroke',
      stroke: opts.halo || '#fff',
      'stroke-width': opts.strokeWidth || 4,
      'stroke-linejoin': 'round'
    });
}

function drawStaticDiagram() {
  base.clear();
  arcsLayer.clear();
  edgesLayer.clear();
  pointsLayer.clear();
  labelsLayer.clear();

  var p0 = points.p0, p3 = points.p3;
  var dx = p3.x - p0.x, dy = p3.y - p0.y;
  var ext1 = { x: p0.x - dx * 0.28, y: p0.y - dy * 0.28 };
  var ext2 = { x: p3.x + dx * 0.26, y: p3.y + dy * 0.26 };
  base.line(ext1.x, ext1.y, ext2.x, ext2.y)
    .stroke({ color: '#000', width: 1.2, dasharray: '5,5', linecap: 'round' });

  var raySpecs = {
    p0: [180, 385, 405, 385],
    p1: [455, 350, 575, 350],
    p2: [532, 255, 640, 255],
    p3: [396, 70, 255, 70],
    p4: [138, 270, 25, 270]
  };
  Object.keys(raySpecs).forEach(function (id) {
    var r = raySpecs[id];
    arrowLine(base, r[0], r[1], r[2], r[3], '#000', 1.2, 13, 7);
  });

  hullOrder.forEach(function (id) {
    var p = points[id];
    base.line(p.x, p.y - 26, p.x, p.y + 28).stroke({ color: '#000', width: 1.1 });
  });

  hullOrder.forEach(function (id) {
    var a = points[id], b = points[nextOf[id]];
    edgesLayer.line(a.x, a.y, b.x, b.y)
      .stroke({ color: hullGray, width: 8, linecap: 'butt', linejoin: 'round' });
  });
  hullOrder.forEach(function (id) {
    var a = points[id], b = points[nextOf[id]];
    edgesLayer.line(a.x, a.y, b.x, b.y)
      .stroke({ color: hullDark, width: 1.15, linecap: 'butt' });
  });

  hullOrder.forEach(function (id) {
    var c = points[id];
    var r = (id === 'p2') ? 56 : (id === 'p3' || id === 'p4') ? 56 : 45;
    arcsLayer.path(arcPath(c.x, c.y, refAngle[id], chosenEndAngle(id), r))
      .fill('none')
      .stroke({ color: '#000', width: 1.1, linecap: 'round' });
  });

  interiors.forEach(function (pt, i) {
    var group = pointsLayer.group();
    group.circle(8).center(pt.x, pt.y).fill('#000');
    group.circle(20).center(pt.x, pt.y).fill({ color: '#fff', opacity: 0 });
