}

var currentId = 'p0';
var currentChain = 'Right chain';
var currentDemoIndex = 0;

function activeRayEndpoints(id) {
  var p = points[id];
  if (refAngle[id] === 0) return [p.x - 20, p.y, p.x + 145, p.y];
  return [p.x + 20, p.y, p.x - 125, p.y];
}

function renderState() {
  dynamic.clear();
  candidateLayer.clear();
  hideTooltip();

  var p = points[currentId];
  var q = points[nextOf[currentId]];
  var r = (currentId === 'p2') ? 59 : (currentId === 'p3' || currentId === 'p4') ? 59 : 48;
  var start = refAngle[currentId], end = chosenEndAngle(currentId);

  dynamic.path(sectorPath(p.x, p.y, start, end, r, 42))
    .fill({ color: accent, opacity: 0.10 })
    .stroke('none');

  dynamic.line(p.x, p.y, q.x, q.y)
    .stroke({ color: accent, width: 10, opacity: 0.72, linecap: 'butt' });
  dynamic.line(p.x, p.y, q.x, q.y)
    .stroke({ color: '#7b3f00', width: 1.8, opacity: 0.95 });

  var ray = activeRayEndpoints(currentId);
  arrowLine(dynamic, ray[0], ray[1], ray[2], ray[3], accent, 2.7, 15, 9);

  dynamic.path(arcPath(p.x, p.y, start, end, r))
    .fill('none')
    .stroke({ color: accent, width: 3.2, linecap: 'round' });

  dynamic.circle(18).center(p.x, p.y).fill('none').stroke({ color: accent, width: 3 });
  dynamic.circle(8).center(p.x, p.y).fill('#000');
  dynamic.front();
  labelsLayer.front();
}

function showCandidate(i, evt) {
  candidateLayer.clear();
  var pt = interiors[i];
  var p = points[currentId];
  var q = points[nextOf[currentId]];
  var cand = sweepAngle(currentId, pt);
  var chosen = sweepAngle(currentId, q);
  var candDeg = deg(cand);
  var chosenDeg = deg(chosen);
  var r = 34;

  candidateLayer.line(p.x, p.y, pt.x, pt.y)
    .stroke({ color: candidateColor, width: 2, dasharray: '5,4', linecap: 'round' });
  candidateLayer.circle(13).center(pt.x, pt.y).fill('none').stroke({ color: candidateColor, width: 2 });

  candidateLayer.path(arcPath(p.x, p.y, refAngle[currentId], refAngle[currentId] + cand, r, 30))
    .fill('none')
    .stroke({ color: candidateColor, width: 2, dasharray: '3,3', linecap: 'round' });

  var labelText = 'candidate ' + candDeg + '°  >  chosen ' + chosenDeg + '°';
  var tx = Math.min(W - 205, Math.max(12, pt.x + 12));
  var ty = Math.max(15, pt.y - 34);
  var t = candidateLayer.text(labelText)
    .move(tx, ty)
    .font({ family: 'sans-serif', size: 12 })
    .fill('#000');
  var box = t.bbox();
  candidateLayer.rect(box.width + 8, box.height + 5)
    .move(box.x - 4, box.y - 2)
    .fill({ color: '#fff', opacity: 0.88 })
    .stroke({ color: candidateColor, width: 1 })
    .back();
  candidateLayer.front();

  showTooltip(
    'Interior point: its angle from ' + points[currentId].label + ' is ' + candDeg +
    '°, larger than the chosen hull angle ' + chosenDeg + '°.',
    evt
  );
}

function setChainLabel(chain) {
  currentChain = chain;
  var box = document.getElementById('chainModeInput');
  var out = document.getElementById('chainModeVal');
  if (box) box.checked = (chain === 'Right chain');
  if (out) out.value = chain;
}

function setCurrentVertex(id) {
  currentId = id;
  var sel = document.getElementById('wrappingStepInput');
  if (sel) sel.value = id;
  renderState();
}

function update_wrappingStep(v) {
  currentDemoIndex = hullOrder.indexOf(v);
  if (currentDemoIndex < 0) currentDemoIndex = 0;
  if (v === 'p3' || v === 'p4') setChainLabel('Left chain');
  else setChainLabel('Right chain');
  setCurrentVertex(v);
  updateStepTextOnly();
}

function toggle_chainMode(on) {
  var chain = on ? 'Right chain' : 'Left chain';
  setChainLabel(chain);
  if (chain === 'Right chain' && (currentId === 'p3' || currentId === 'p4')) {
    currentDemoIndex = 0;
    setCurrentVertex('p0');
  } else if (chain === 'Left chain' && (currentId === 'p0' || currentId === 'p1' || currentId === 'p2')) {
    currentDemoIndex = 3;
    setCurrentVertex('p3');
  } else {
    renderState();
  }
  updateStepTextOnly();
}

var demoSteps = [
  {
    title: 'Start at the lowest hull point',
    narration: 'From p_0, the active reference ray points to the right. The smallest polar angle among all candidate points selects p_1, so the first hull edge is p_0p_1.',
    state: { wrappingStep: 'p0', chainMode: 'Right chain' }
  },
  {
    title: 'Continue up the right chain',
    narration: 'At p_1, the same rightward reference direction is used. The smallest angle now points to p_2, while the interior points fall inside the polygon and have larger candidate angles.',
    state: { wrappingStep: 'p1', chainMode: 'Right chain' }
  },
  {
    title: 'Reach the highest point',
    narration: 'From p_2, the smallest sweep reaches p_3. This completes the right chain from the lowest point to the highest point.',
    state: { wrappingStep: 'p2', chainMode: 'Right chain' }
  },
  {
    title: 'Flip to the left chain',
    narration: 'At p_3, the construction switches to the left chain, so the horizontal reference ray flips direction. With the leftward reference, the smallest polar angle selects p_4.',
    state: { wrappingStep: 'p3', chainMode: 'Left chain' }
  },
  {
    title: 'Close the hull',
    narration: 'At p_4, the left-chain rule continues and the smallest angle returns to p_0. The thick gray polygon is exactly the sequence of vertices chosen by these local angle tests.',
    state: { wrappingStep: 'p4', chainMode: 'Left chain' }
  }
];

function applyDemoStep(i) {
  currentDemoIndex = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[currentDemoIndex];
  setChainLabel(step.state.chainMode);
  setCurrentVertex(step.state.wrappingStep);
  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
  if (n) n.textContent = step.narration;
  if (l) l.textContent = (currentDemoIndex + 1) + ' / ' + demoSteps.length;
}

function updateStepTextOnly() {
  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
  var step = demoSteps[currentDemoIndex] || demoSteps[0];
  if (n) n.textContent = step.narration;
  if (l) l.textContent = (currentDemoIndex + 1) + ' / ' + demoSteps.length;
}

function prevStep() {
  applyDemoStep(currentDemoIndex - 1);
}

function nextStep() {
  applyDemoStep(currentDemoIndex + 1);
}

drawStaticDiagram();
applyDemoStep(0);
window.__markRendered();
// @FIGURE_CODE_END

