function arrowLine(g, x1, y1, x2, y2, color, width, headLen, headWidth) {
  headLen = headLen || 14;
  headWidth = headWidth || 8;
  var line = g.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / len, uy = dy / len;
  var bx = x2 - ux * headLen, by = y2 - uy * headLen;
  var px = -uy, py = ux;
  g.polygon([
    [x2, y2],
    [bx + px * headWidth / 2, by + py * headWidth / 2],
    [bx - px * headWidth / 2, by - py * headWidth / 2]
  ]).fill(color).stroke('none');
  return line;
}

function mathAngle(from, to) {
  var a = Math.atan2(-(to.y - from.y), to.x - from.x);
  if (a < 0) a += Math.PI * 2;
  return a;
}

function sweepAngle(fromId, toPoint) {
  var a = mathAngle(points[fromId], toPoint);
  return (a - refAngle[fromId] + Math.PI * 2) % (Math.PI * 2);
