function arcPath(cx, cy, start, end, r, steps) {
  steps = steps || 36;
  var d = '';
  for (var i = 0; i <= steps; i++) {
    var t = start + (end - start) * i / steps;
    var x = cx + r * Math.cos(t);
    var y = cy - r * Math.sin(t);
    d += (i === 0 ? 'M' : 'L') + x.toFixed(2) + ',' + y.toFixed(2);
  }
  return d;
}

function sectorPath(cx, cy, start, end, r, steps) {
  steps = steps || 36;
  var d = 'M' + cx + ',' + cy + ' ';
  for (var i = 0; i <= steps; i++) {
    var t = start + (end - start) * i / steps;
    var x = cx + r * Math.cos(t);
    var y = cy - r * Math.sin(t);
    d += (i === 0 ? 'L' : 'L') + x.toFixed(2) + ',' + y.toFixed(2) + ' ';
  }
  return d + 'Z';
}

