var W = 900, H = 610;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var accent = '#d97918';
var accentDark = '#8a4a08';
var candidateColor = '#2e63d8';
var hullGray = '#a7a7a7';
var hullDark = '#111';

var points = {
  p0: { x: 275, y: 525, label: 'p₀' },
  p1: { x: 720, y: 470, label: 'p₁' },
  p2: { x: 795, y: 340, label: 'p₂' },
  p3: { x: 350, y: 85, label: 'p₃' },
  p4: { x: 145, y: 375, label: 'p₄' }
};

var hullOrder = ['p0', 'p1', 'p2', 'p3', 'p4'];
var nextOf = { p0: 'p1', p1: 'p2', p2: 'p3', p3: 'p4', p4: 'p0' };
var refAngle = { p0: 0, p1: 0, p2: 0, p3: Math.PI, p4: Math.PI };

var interiors = [
  { x: 255, y: 275 },
  { x: 345, y: 265 },
  { x: 430, y: 265 },
  { x: 495, y: 245 },
  { x: 383, y: 315 },
  { x: 640, y: 265 },
  { x: 678, y: 340 },
  { x: 705, y: 415 }
];

var guideActive = false;
var currentId = 'p0';
var currentChain = 'Right chain';
var currentDemoIndex = 0;

var baseLayer = draw.group();
var arcsLayer = draw.group();
var hullLayer = draw.group();
var pointsLayer = draw.group();
var dynamicLayer = draw.group();
var candidateLayer = draw.group();
var labelsLayer = draw.group();

function arrowLine(g, x1, y1, x2, y2, color, width, headLen, headWidth, opacity) {
  headLen = headLen || 15;
  headWidth = headWidth || 9;
  var line = g.line(x1, y1, x2, y2).stroke({
    color: color,
    width: width,
    linecap: 'butt'
  }).opacity(opacity == null ? 1 : opacity);
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / len, uy = dy / len;
  var bx = x2 - ux * headLen, by = y2 - uy * headLen;
  var px = -uy, py = ux;
  g.polygon([
    [x2, y2],
    [bx + px * headWidth / 2, by + py * headWidth / 2],
    [bx - px * headWidth / 2, by - py * headWidth / 2]
  ]).fill(color).opacity(opacity == null ? 1 : opacity).stroke('none');
  return line;
}

function mathAngle(from, to) {
  var a = Math.atan2(-(to.y - from.y), to.x - from.x);
  if (a < 0) a += Math.PI * 2;
  return a;
}

function sweepAngle(fromId, toPoint) {
  return (mathAngle(points[fromId], toPoint) - refAngle[fromId] + Math.PI * 2) % (Math.PI * 2);
}

function deg(rad) {
  return Math.round(rad * 180 / Math.PI);
}

function chosenEndAngle(id) {
  var raw = mathAngle(points[id], points[nextOf[id]]);
  while (raw < refAngle[id]) raw += Math.PI * 2;
  return raw;
}

function arcPath(cx, cy, start, end, r, steps) {
  steps = steps || 48;
  var d = '';
  for (var i = 0; i <= steps; i++) {
    var t = start + (end - start) * i / steps;
    var x = cx + r * Math.cos(t);
    var y = cy - r * Math.sin(t);
    d += (i === 0 ? 'M' : 'L') + x.toFixed(2) + ',' + y.toFixed(2);
  }
  return d;
}

function sectorPath(cx, cy, start, end, r, steps) {
  steps = steps || 48;
  var d = 'M' + cx + ',' + cy + ' ';
  for (var i = 0; i <= steps; i++) {
    var t = start + (end - start) * i / steps;
    var x = cx + r * Math.cos(t);
    var y = cy - r * Math.sin(t);
    d += 'L' + x.toFixed(2) + ',' + y.toFixed(2) + ' ';
  }
  return d + 'Z';
}

function textHalo(g, txt, x, y, opts) {
  opts = opts || {};
  return g.text(txt)
    .move(x, y)
    .font({
      family: opts.family || 'Georgia, Times New Roman, serif',
      size: opts.size || 26,
      style: opts.style || 'italic',
      anchor: opts.anchor || 'start'
    })
    .fill(opts.fill || '#000')
    .attr({
      'paint-order': 'stroke',
      stroke: opts.halo || '#fff',
      'stroke-width': opts.strokeWidth || 4,
      'stroke-linejoin': 'round'
    });
}

function drawStaticDiagram() {
  baseLayer.clear();
  arcsLayer.clear();
  hullLayer.clear();
  pointsLayer.clear();
  labelsLayer.clear();

  var p0 = points.p0, p3 = points.p3;
  var dx = p3.x - p0.x, dy = p3.y - p0.y;
  var ext1 = { x: p0.x - dx * 0.20, y: p0.y - dy * 0.20 };
  var ext2 = { x: p3.x + dx * 0.18, y: p3.y + dy * 0.18 };
  baseLayer.line(ext1.x, ext1.y, ext2.x, ext2.y)
    .stroke({ color: '#000', width: 1.2, dasharray: '6,6', linecap: 'round' });

  arrowLine(baseLayer, 235, points.p0.y, 535, points.p0.y, '#000', 1.35, 17, 10);
  arrowLine(baseLayer, 685, points.p1.y, 815, points.p1.y, '#000', 1.35, 17, 10);
  arrowLine(baseLayer, 758, points.p2.y, 888, points.p2.y, '#000', 1.35, 17, 10);
  arrowLine(baseLayer, 390, points.p3.y, 205, points.p3.y, '#000', 1.35, 17, 10);
  arrowLine(baseLayer, 184, points.p4.y, 34, points.p4.y, '#000', 1.35, 17, 10);

  hullOrder.forEach(function (id) {
    var p = points[id];
    var half = (id === 'p0' || id === 'p1' || id === 'p2') ? 38 : 36;
    baseLayer.line(p.x, p.y - half, p.x, p.y + half)
      .stroke({ color: '#000', width: 1.15, linecap: 'butt' });
  });

  var arcR = { p0: 225, p1: 78, p2: 74, p3: 118, p4: 74 };
  hullOrder.forEach(function (id) {
    var p = points[id];
    arcsLayer.path(arcPath(p.x, p.y, refAngle[id], chosenEndAngle(id), arcR[id], 60))
      .fill('none')
      .stroke({ color: '#000', width: 1.25, linecap: 'round' });
  });

  hullOrder.forEach(function (id) {
    var a = points[id], b = points[nextOf[id]];
    hullLayer.line(a.x, a.y, b.x, b.y)
      .stroke({ color: hullGray, width: 10, linecap: 'butt', linejoin: 'round' });
  });
  hullOrder.forEach(function (id) {
    var a = points[id], b = points[nextOf[id]];
    hullLayer.line(a.x, a.y, b.x, b.y)
      .stroke({ color: hullDark, width: 1.25, linecap: 'butt', linejoin: 'round' });
  });

  interiors.forEach(function (pt, i) {
    var g = pointsLayer.group();
    g.circle(10).center(pt.x, pt.y).fill('#000');
    g.circle(26).center(pt.x, pt.y).fill({ color: '#fff', opacity: 0 });
    g.css('cursor', 'pointer')
      .on('mousemove', function (e) { showCandidate(i, e); })
      .on('mouseleave', function () {
        candidateLayer.clear();
        hideTooltip();
      })
      .on('click', function () {
        var q = points[nextOf[currentId]];
        showPopup(
          'Candidate angle test',
          'From the current vertex, this point is tested just like every other point. It is skipped because its candidate angle is larger than the angle to ' + q.label + ', the next hull vertex.'
        );
      });
  });

  hullOrder.forEach(function (id) {
    var p = points[id];
    var g = pointsLayer.group();
    g.circle(11).center(p.x, p.y).fill('#000');
    g.circle(27).center(p.x, p.y).fill({ color: '#fff', opacity: 0 });
    g.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(points[id].label + ': convex-hull vertex', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup(
          points[id].label,
          'This point lies on the convex hull. When it becomes current, Jarvis’s march chooses the next hull vertex by the smallest polar-angle sweep from the horizontal reference ray.'
        );
      });
  });

  textHalo(labelsLayer, 'p₀', 288, 533, { size: 31 });
  textHalo(labelsLayer, 'p₁', 733, 478, { size: 31 });
  textHalo(labelsLayer, 'p₂', 808, 348, { size: 31 });
  textHalo(labelsLayer, 'p₃', 362, 94, { size: 31 });
  textHalo(labelsLayer, 'p₄', 113, 347, { size: 31 });

  textHalo(labelsLayer, 'left chain', 292, 24, { size: 28, style: 'normal', anchor: 'middle', strokeWidth: 5 });
  textHalo(labelsLayer, 'right chain', 430, 24, { size: 28, style: 'normal', anchor: 'middle', strokeWidth: 5 });
  arrowLine(labelsLayer, 332, 61, 282, 61, '#000', 1.25, 15, 9);
  arrowLine(labelsLayer, 382, 61, 435, 61, '#000', 1.25, 15, 9);

  textHalo(labelsLayer, 'left chain', 190, 575, { size: 28, style: 'normal', anchor: 'middle', strokeWidth: 5 });
  textHalo(labelsLayer, 'right chain', 395, 575, { size: 28, style: 'normal', anchor: 'middle', strokeWidth: 5 });
  arrowLine(labelsLayer, 246, 558, 184, 558, '#000', 1.25, 15, 9);
  arrowLine(labelsLayer, 302, 558, 365, 558, '#000', 1.25, 15, 9);
}

function activeRayEndpoints(id) {
  if (id === 'p0') return [238, points.p0.y, 540, points.p0.y];
  if (id === 'p1') return [685, points.p1.y, 820, points.p1.y];
  if (id === 'p2') return [758, points.p2.y, 890, points.p2.y];
  if (id === 'p3') return [390, points.p3.y, 202, points.p3.y];
  return [184, points.p4.y, 32, points.p4.y];
}

function renderState() {
  dynamicLayer.clear();
  candidateLayer.clear();
  hideTooltip();

  if (!guideActive) {
    labelsLayer.front();
    return;
  }

  var p = points[currentId];
  var q = points[nextOf[currentId]];
  var r = { p0: 225, p1: 78, p2: 74, p3: 118, p4: 74 }[currentId];
  var start = refAngle[currentId];
  var end = chosenEndAngle(currentId);

  dynamicLayer.path(sectorPath(p.x, p.y, start, end, r, 60))
    .fill({ color: accent, opacity: 0.055 })
    .stroke('none');

  dynamicLayer.line(p.x, p.y, q.x, q.y)
    .stroke({ color: accent, width: 9, opacity: 0.38, linecap: 'butt' });
  dynamicLayer.line(p.x, p.y, q.x, q.y)
    .stroke({ color: accentDark, width: 2.4, opacity: 0.85, linecap: 'butt' });

  var ray = activeRayEndpoints(currentId);
  arrowLine(dynamicLayer, ray[0], ray[1], ray[2], ray[3], accent, 2.5, 17, 10, 0.88);

  dynamicLayer.path(arcPath(p.x, p.y, start, end, r, 60))
    .fill('none')
    .stroke({ color: accent, width: 3.0, opacity: 0.9, linecap: 'round' });

  dynamicLayer.circle(24).center(p.x, p.y)
    .fill('none')
    .stroke({ color: accent, width: 3, opacity: 0.9 });
  dynamicLayer.circle(11).center(p.x, p.y).fill('#000');

  dynamicLayer.front();
  candidateLayer.front();
  labelsLayer.front();
}

function showCandidate(i, evt) {
  candidateLayer.clear();

  var pt = interiors[i];
  var p = points[currentId];
  var q = points[nextOf[currentId]];
  var cand = sweepAngle(currentId, pt);
  var chosen = sweepAngle(currentId, q);
  var candDeg = deg(cand);
  var chosenDeg = deg(chosen);

  candidateLayer.line(p.x, p.y, pt.x, pt.y)
    .stroke({ color: candidateColor, width: 2, dasharray: '6,5', linecap: 'round' });
  candidateLayer.circle(16).center(pt.x, pt.y)
    .fill('none')
    .stroke({ color: candidateColor, width: 2 });

  var smallR = 46;
  candidateLayer.path(arcPath(p.x, p.y, refAngle[currentId], refAngle[currentId] + cand, smallR, 34))
    .fill('none')
    .stroke({ color: candidateColor, width: 2, dasharray: '3,3', linecap: 'round' });

  var labelText = 'candidate ' + candDeg + '° > chosen ' + chosenDeg + '°';
  var tx = Math.min(W - 250, Math.max(14, pt.x + 16));
  var ty = Math.max(18, pt.y - 42);
  var t = candidateLayer.text(labelText)
    .move(tx, ty)
    .font({ family: 'sans-serif', size: 15 })
    .fill('#000')
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  var box = t.bbox();
  candidateLayer.rect(box.width + 10, box.height + 7)
    .move(box.x - 5, box.y - 3)
    .fill({ color: '#fff', opacity: 0.92 })
    .stroke({ color: candidateColor, width: 1 })
    .back();

  candidateLayer.front();
  labelsLayer.front();

  showTooltip(
    'Interior point: its angle from ' + points[currentId].label + ' is ' + candDeg +
    '°, larger than the chosen hull angle ' + chosenDeg + '°.',
    evt
  );
}

function setChainLabel(chain) {
  currentChain = chain;
  var box = document.getElementById('chainModeInput');
  var out = document.getElementById('chainModeVal');
  if (box) box.checked = (chain === 'Right chain');
  if (out) out.value = chain;
}

function setCurrentVertex(id) {
  currentId = id;
  var sel = document.getElementById('wrappingStepInput');
  if (sel) sel.value = id;
  renderState();
}

function update_wrappingStep(v) {
  guideActive = true;
  currentDemoIndex = hullOrder.indexOf(v);
  if (currentDemoIndex < 0) currentDemoIndex = 0;
  if (v === 'p3' || v === 'p4') setChainLabel('Left chain');
  else setChainLabel('Right chain');
  setCurrentVertex(v);
  updateStepTextOnly();
}

function toggle_chainMode(on) {
  guideActive = true;
  var chain = on ? 'Right chain' : 'Left chain';
  setChainLabel(chain);

  if (chain === 'Right chain' && (currentId === 'p3' || currentId === 'p4')) {
    currentDemoIndex = 0;
    setCurrentVertex('p0');
  } else if (chain === 'Left chain' && (currentId === 'p0' || currentId === 'p1' || currentId === 'p2')) {
    currentDemoIndex = 3;
    setCurrentVertex('p3');
  } else {
    renderState();
  }
  updateStepTextOnly();
}

var demoSteps = [
  {
    title: 'Start at the lowest hull point',
    narration: 'From p_0, the active reference ray points to the right. The smallest polar angle among all candidate points selects p_1, so the first hull edge is p_0p_1.',
    state: { wrappingStep: 'p0', chainMode: 'Right chain' }
  },
  {
    title: 'Continue up the right chain',
    narration: 'At p_1, the same rightward reference direction is used. The smallest angle now points to p_2, while the interior points fall inside the polygon and have larger candidate angles.',
    state: { wrappingStep: 'p1', chainMode: 'Right chain' }
  },
  {
    title: 'Reach the highest point',
    narration: 'From p_2, the smallest sweep reaches p_3. This completes the right chain from the lowest point to the highest point.',
    state: { wrappingStep: 'p2', chainMode: 'Right chain' }
  },
  {
    title: 'Flip to the left chain',
    narration: 'At p_3, the construction switches to the left chain, so the horizontal reference ray flips direction. With the leftward reference, the smallest polar angle selects p_4.',
    state: { wrappingStep: 'p3', chainMode: 'Left chain' }
  },
  {
    title: 'Close the hull',
    narration: 'At p_4, the left-chain rule continues and the smallest angle returns to p_0. The thick gray polygon is exactly the sequence of vertices chosen by these local angle tests.',
    state: { wrappingStep: 'p4', chainMode: 'Left chain' }
  }
];

function applyDemoStep(i, activateGuide) {
  currentDemoIndex = (i + demoSteps.length) % demoSteps.length;
  if (activateGuide) guideActive = true;

  var step = demoSteps[currentDemoIndex];
  setChainLabel(step.state.chainMode);
  setCurrentVertex(step.state.wrappingStep);

  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
  if (n) n.textContent = step.narration;
  if (l) l.textContent = (currentDemoIndex + 1) + ' / ' + demoSteps.length;
}

function updateStepTextOnly() {
  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
  var step = demoSteps[currentDemoIndex] || demoSteps[0];
  if (n) n.textContent = step.narration;
  if (l) l.textContent = (currentDemoIndex + 1) + ' / ' + demoSteps.length;
}

function prevStep() {
  applyDemoStep(currentDemoIndex - 1, true);
}

function nextStep() {
  applyDemoStep(currentDemoIndex + 1, true);
}

drawStaticDiagram();
applyDemoStep(0, false);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

